                     AND NULLIF(regexp_replace(l.nome, '[^0-9]', '', 'g'), '')::int = a.numero);

-- Conferência: armários por corredor e quantos estão na parede.
SELECT l.corredor, count(*) AS total, count(l.item_id) AS na_parede FROM lockers l JOIN schools s ON s.id = l.school_id
 WHERE s.codigo = 'etec-043' GROUP BY 1 ORDER BY 1;
